    digits = []
    for c in s:
        if c == ' ':
            continue
        if c not in '0123456789':
            raise ValueError(c)
        digits.append(int(c))
    if len(digits) < 2:
        return False
    total = 0
    for i, d in enumerate(reversed(digits)):
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0

